{
  "initiative": "Kill the top causes of unplanned downtime across all three plants",
  "okrs": [
    {
      "objective": "Downtime stops being the thing that decides our output",
      "key_results": [
        "Unplanned downtime down 30% against the current baseline",
        "Top ten failure causes each have a named fix in flight",
        "Downtime dashboard live for every plant lead"
      ]
    }
  ],
  "sprint_plan": [
    {
      "sprint": 1,
      "weeks": "1-3",
      "focus": "Instrument the ten worst assets",
      "owner": "Reliability lead",
      "ships": "Live telemetry from every asset on the critical list"
    },
    {
      "sprint": 2,
      "weeks": "4-6",
      "focus": "Fix the two biggest repeat failures",
      "owner": "Maintenance lead",
      "ships": "Two permanent fixes in production at the pilot plant"
    },
    {
      "sprint": 3,
      "weeks": "7-9",
      "focus": "Iterate on the alerting thresholds",
      "owner": "Reliability lead",
      "ships": "Alerting tuned to under one false page per day"
    },
    {
      "sprint": 4,
      "weeks": "10-12",
      "focus": "Roll the pattern to the other two plants",
      "owner": "Plant operations lead",
      "ships": "Same telemetry and alerting running at all three plants"
    }
  ],
  "blockers": [
    "Oldest plant has no network drop on the shop floor",
    "Maintenance history lives in a system nobody can export from"
  ],
  "success_metric": "Unplanned downtime hours per month, measured per plant",
  "timeline_weeks": 12
}

{
  "initiative": "Get a second casting supplier live so one vendor stops holding the line",
  "okrs": [
    {
      "objective": "No single vendor can stop our production line",
      "key_results": [
        "Second supplier producing at rate for the two highest-volume part numbers",
        "Dual routing live in the planning system"
      ]
    }
  ],
  "sprint_plan": [
    {
      "sprint": 1,
      "weeks": "1-4",
      "focus": "Shortlist and assess three candidate suppliers",
      "owner": "Supply chain lead",
      "ships": "Scored shortlist with one supplier picked"
    },
    {
      "sprint": 2,
      "weeks": "5-8",
      "focus": "First parts and measurement checks",
      "owner": "Quality engineer",
      "ships": "First parts measured and accepted"
    },
    {
      "sprint": 3,
      "weeks": "9-12",
      "focus": "Ramp to production volume",
      "owner": "Supply chain lead",
      "ships": "Second supplier producing at rate"
    }
  ],
  "blockers": [
    "Tooling budget not yet approved",
    "Legal wants an indemnity clause the vendor has refused twice"
  ],
  "success_metric": "Share of volume on the two highest-volume parts that a second supplier can cover",
  "timeline_weeks": 12
}

{
  "initiative": "Take 20% out of what it costs us to serve our biggest accounts",
  "okrs": [
    {
      "objective": "Serving our largest accounts stops eating margin",
      "key_results": [
        "Cost to serve per large account down 20%",
        "No drop in reliability metrics for those accounts"
      ]
    }
  ],
  "sprint_plan": [
    {
      "sprint": 1,
      "weeks": "1-2",
      "focus": "Get the real cost per account from finance",
      "owner": "Analytics lead",
      "ships": "Cost-to-serve model the finance team signs up to"
    },
    {
      "sprint": 2,
      "weeks": "3-5",
      "focus": "Automate the three most manual support paths",
      "owner": "Support engineering lead",
      "ships": "Three manual paths replaced with self-serve"
    },
    {
      "sprint": 3,
      "weeks": "6-8",
      "focus": "Iterate on the accounts still above target",
      "owner": "Account operations lead",
      "ships": "Fixes for the five most expensive accounts"
    },
    {
      "sprint": 4,
      "weeks": "9-10",
      "focus": "Lock the metric into the monthly review",
      "owner": "Analytics lead",
      "ships": "Cost per account on the standing review deck"
    }
  ],
  "blockers": [
    "Finance data has a two-month lag we cannot shorten yet"
  ],
  "success_metric": "Fully loaded cost to serve per large account, tracked monthly",
  "timeline_weeks": 10
}

{
  "initiative": "Get new customers to first value in days, not a month",
  "okrs": [
    {
      "objective": "A new customer reaches first value without waiting on us",
      "key_results": [
        "Median time to first value under three days",
        "Half of new accounts activate with zero support contact"
      ]
