      "ships": "Step-by-step timing for the current activation path"
    },
    {
      "sprint": 2,
      "weeks": "3-5",
      "focus": "Automate the two slowest handoffs",
      "owner": "Platform engineer",
      "ships": "Two manual handoffs replaced with automation"
    },
    {
      "sprint": 3,
      "weeks": "6-8",
      "focus": "Guided in-product setup",
      "owner": "Product engineer",
      "ships": "In-app setup flow live behind a flag"
    },
    {
      "sprint": 4,
      "weeks": "9-10",
      "focus": "Turn it on for everyone",
      "owner": "Growth engineer",
      "ships": "New activation path at 100% rollout"
    }
  ],
  "blockers": [
    "Provisioning still needs a manual credit check for some regions"
  ],
  "success_metric": "Median time from contract signature to first value",
  "timeline_weeks": 10
}

{
  "initiative": "Move reporting off the legacy warehouse before the contract renews",
  "okrs": [
    {
      "objective": "Reporting runs entirely on the new warehouse",
      "key_results": [
        "All report definitions ported and reconciled",
        "Legacy warehouse switched off before renewal"
      ]
    }
  ],
  "sprint_plan": [
    {
      "sprint": 1,
      "weeks": "1-3",
      "focus": "Port the top ten report definitions",
      "owner": "Data platform lead",
      "ships": "Ten highest-traffic reports live on the new warehouse"
    },
    {
      "sprint": 2,
      "weeks": "4-6",
      "focus": "Reconcile numbers against the old system",
      "owner": "Analytics engineer",
      "ships": "Reconciliation report with differences explained"
    },
    {
      "sprint": 3,
      "weeks": "7-9",
      "focus": "Port the long tail",
      "owner": "Analytics engineer",
      "ships": "Remaining report definitions live"
    },
    {
      "sprint": 4,
      "weeks": "10-12",
      "focus": "Cut over and decommission",
      "owner": "Data platform lead",
      "ships": "Legacy warehouse switched off"
    }
