    {
      "sprint": 4,
      "weeks": "10-12",
      "focus": "Iterate on whatever is still late",
      "owner": "Planning lead",
      "ships": "Fixes for the remaining late causes"
    }
  ],
  "blockers": [
    "Order dates are entered by hand in two regions"
  ],
  "success_metric": "On-time delivery percentage per product family, tracked monthly",
